"""Storage for files generated by tool calls (currently: run_python_code
output files, e.g. a matplotlib plot) so they can be served back to the UI.

Distinct from DocumentStore (which owns exactly one `document.pdf` per id):
an artifact id can hold several files — a run might produce more than one
plot — each keeping its original filename.
"""

from pathlib import Path
from uuid import UUID, uuid4

from backend.config import settings


class ArtifactStore:

    def __init__(self, root: str | Path | None = None):
        self.root = Path(root or settings.artifact_store.dir)
        self.root.mkdir(parents=True, exist_ok=True)

    def get_artifact_dir(self, artifact_id: str) -> Path:
        # Validate that the ID is a UUID before it's ever used to build a path.
        UUID(artifact_id)
        return self.root / artifact_id

    def save(self, data: bytes, filename: str) -> str:
        """Store one file under a fresh artifact id. Returns the artifact id.

        `filename` must be a bare filename (no path separators) — callers
        are expected to pass a name straight from a directory listing, not
        anything derived from user/tool input.
        """

        safe_name = Path(filename).name
        if not safe_name or safe_name != filename:
            raise ValueError(f"filename must be a bare filename, got {filename!r}")

        artifact_id = str(uuid4())
        artifact_dir = self.get_artifact_dir(artifact_id)
        artifact_dir.mkdir(parents=True, exist_ok=True)
        (artifact_dir / safe_name).write_bytes(data)
        return artifact_id

    def get_path(self, artifact_id: str, filename: str) -> Path | None:
        """Resolve a stored file's path, or None if it doesn't exist.

        `filename` is untrusted (comes from a URL path segment) — resolved
        against `Path(filename).name` so it can never escape the artifact's
        own directory.
        """

        try:
            artifact_dir = self.get_artifact_dir(artifact_id)
        except ValueError:
            return None

        safe_name = Path(filename).name
        path = artifact_dir / safe_name
        if not path.is_file():
            return None
        return path
